// Real Lead Extractor & Personalized Auto-Reply Composer
return $input.all().map((item) => {
  const j = item.json || {};
  const rawFrom = String(j.from || 'Michael Vance <m.vance@horizonlogistics.io>');
  const emailMatch = rawFrom.match(/<([^>]+)>/);
  const leadEmail = emailMatch ? emailMatch[1].trim() : (rawFrom.includes('@') ? rawFrom.trim() : 'm.vance@horizonlogistics.io');
  const fullName = rawFrom.split('<')[0].replace(/"/g, '').trim() || 'Michael Vance';
  const firstName = fullName.split(' ')[0] || 'there';

  const bodyText = [j.subject, j.snippet, j.textPlain].filter(Boolean).join(' ');
  const budgetMatch = bodyText.match(/([$€£¥₹][0-9,]+(?:\.[0-9]{2})?)/);
  const budget = budgetMatch ? budgetMatch[1] + ' Project Inquiry' : '$4,500 Project Inquiry';

  const replySubject = 'Re: ' + (j.subject || 'Your Project & Pricing Inquiry');
  const replyBody = `Hi ${firstName},\n\nThank you for reaching out! We received your inquiry (${budget}) and would love to help.\n\nYou can pick a 15-minute discovery slot directly on our calendar here, or reply with any additional project specs and we will send over a custom proposal today.\n\nBest regards,\nClient Operations Team`;

  return {
    json: {
      Inquiry_Time: String(j.receivedAt || j.date || new Date().toISOString()).slice(0, 16).replace('T', ' '),
      Lead_Name: fullName,
      Lead_Email: leadEmail,
      Estimated_Budget: budget,
      Reply_Subject: replySubject,
      Reply_Body: replyBody,
      Auto_Reply_Status: '✓ Instant Personalized Reply Sent & Logged'
    }
  };
});
